// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Öğretici ve kişisel hayatı konu alan metinler: deneme, gezi yazısı, anı, biyografi, mektup ve günlük klasikleri (Montaigne, Evliya Çelebi, Ataç, Meriç) (kolay).
const ozLiterature17Kolay = <(String, String, List<String>, String)>[
  ('Yazarın herhangi bir konuyu kesin kurallara varmadan ve kanıtlama amacı gütmeden kendi kişisel görüşleriyle işlediği öğretici metin türü hangisidir?', 'Deneme', ['Makale ve bilimsel inceleme yazısı', 'Biyografi ve öz yaşam öyküsü', 'Gezi yazısı ve seyahatname'], 'Deneme türünde yazar kendi kendisiyle konuşuyormuş gibi samimi bir üslupla kişisel düşüncelerini kanıtlama kaygısı taşımadan aktarır.'),
  ('Dünya edebiyatında deneme türünün kurucusu kabul edilen ve 16. yüzyılda yayımladığı "Denemeler" (Essais) adlı eseriyle tanınan Fransız yazar kimdir?', 'Michel de Montaigne', ['Jean-Jacques Rousseau', 'Charles-Louis de Montesquieu', 'François-Marie Arouet Voltaire'], 'Michel de Montaigne, 1580 yılında yayımlamaya başladığı Essais adlı yapıtıyla deneme türünün hem isim babası hem de kurucusu olmuştur.'),
  ('İngiliz edebiyatında deneme türünün öncüsü sayılan ve özlü, nesnel üslubuyla Montaigne\'den ayrılan düşünür ve yazar kimdir?', 'Francis Bacon', ['Thomas Hobbes', 'John Stuart Mill', 'Bertrand Russell'], 'Francis Bacon, 1597\'de yayımladığı Essays adlı eseriyle İngiliz edebiyatında deneme türünü başlatmış ve daha öğretici, özlü bir biçem geliştirmiştir.'),
  ('Yazarın güncel ya da genel bir konuyu okuyucuyla karşılıklı konuşuyormuş gibi senli benli ve içten bir dille ele aldığı yazı türüne ne ad verilir?', 'Söyleşi (Sohbet)', ['Eleştiri (Tenkit)', 'Tutanak ve rapor', 'Anı (Hatırat)'], 'Söyleşi türünde yazar, okuyucuya sorular yönelterek ve samimi bir konuşma havası kurarak düşüncelerini paylaşır.'),
  ('Gazete ve dergilerin belirli sütunlarında güncel siyasal, toplumsal veya kültürel olayları kanıtlama zorunluluğu olmadan yorumlayan kısa yazılara ne denir?', 'Fıkra (Köşe yazısı)', ['Röportaj ve mülakat', 'Monografi incelemesi', 'Günlük (Günce)'], 'Edebiyat terimi olarak fıkra, süreli yayınlarda güncel konuları nükteli ve akıcı bir dille işleyen köşe yazısıdır.'),
  ('Cumhuriyet dönemi Türk edebiyatında deneme ve öznel eleştiri türlerinin en önemli ustalarından biri olan, "Günlerin Getirdiği" ve "Karalama Defteri" adlı eserlerin yazarı kimdir?', 'Nurullah Ataç', ['Ahmet Haşim', 'Falih Rıfkı Atay', 'Yakup Kadri Karaosmanoğlu'], 'Nurullah Ataç, Türkçenin özleşmesi savunusu, devrik cümle kullanımı ve deneme türündeki öncü yapıtlarıyla tanınır.'),
  ('Anadolu hümanizmini ve kültürünü savunan, "Mavi ve Kara" adlı ünlü deneme kitabının yazarı ve çevirmen kimdir?', 'Sabahattin Eyüboğlu', ['Bedri Rahmi Eyüboğlu', 'Azra Erhat', 'Halikarnas Balıkçısı'], 'Sabahattin Eyüboğlu, Mavi ve Kara adlı yapıtında Anadolu kültürünü, halk sanatını ve hümanist düşünceyi deneme üslubuyla işlemiştir.'),
  ('"Günlerin Götürdüğü", "Edebiyat Konuşmaları" ve "Denemeler" adlı eserleriyle tanınan, estetik ve sanat tarihi alanlarında da uzmanlaşmış deneme yazarımız kimdir?', 'Suut Kemal Yetkin', ['Mehmet Kaplan', 'Tahsin Yücel', 'Berna Moran'], 'Suut Kemal Yetkin, yalın ve berrak Türkçesiyle sanat, edebiyat ve estetik üzerine nitelikli denemeler kaleme almıştır.'),
  ('Nurullah Ataç\'ın Türk dilinde savunduğu ve kendi denemelerinde yoğun biçimde uyguladığı en belirgin iki dil ve üslup özelliği nedir?', 'Öztürkçecilik (dil devrimi) ve devrik cümle kullanımı', ['Arapça-Farsça tamlamalar ve aruz vezniyle düzyazı', 'Ağız ve şive taklitleri ile uzun bağlı cümle yapıları', 'Batı dillerinden olduğu gibi alınan sözcükler ve resmî üslup'], 'Nurullah Ataç, yabancı kökenli sözcüklerin yerine Türkçe türetmelerin kullanılmasını ve konuşma dilinin doğallığını yansıtan devrik cümleyi savunmuştur.'),
  ('Türk edebiyatında Tanzimat\'tan önce divan edebiyatı geleneğinde fıkra, söyleşi ve deneme gibi gazete çevresinde gelişen öğretici türlerin tam karşılığının bulunmamasının temel nedeni nedir?', 'Özel gazetelerin ve süreli yayınların ancak Tanzimat döneminde çıkarılmaya başlanması', ['Divan şairlerinin düzyazı biçiminde hiçbir eser kaleme almamış olmaları', 'Matbaanın Osmanlı topraklarına Cumhuriyet\'in ilanından sonra getirilmesi', 'Okuryazar kesimin yalnızca tiyatro metinlerine ve romanlara ilgi göstermesi'], 'Deneme, fıkra ve söyleşi gibi modern öğretici türler Türk edebiyatına Tanzimat döneminde gazete ve dergiciliğin doğuşuyla girmiştir.'),
  ('Söyleşi (sohbet) türündeki yazılarda atasözlerine, deyimlere, nüktelere ve halk söyleyişlerine sıkça yer verilmesinin temel amacı nedir?', 'Okuyucuyla sıcak, doğal ve içten bir iletişim kurarak okuma akıcılığını artırmak', ['Yazarın halk edebiyatı alanında akademik doktora derecesi bulunduğunu kanıtlamak', 'Metnin sayfa sayısını uzatarak gazetedeki boş sütunları zahmetsizce doldurmak', 'Resmî yazışma kurallarına uygun, ağırbaşlı ve mesafeli bir devlet dili yaratmak'], 'Söyleşi türü konuşma dilinin canlılığına dayandığı için deyimler, nükteler ve atasözleri anlatıma doğallık ve samimiyet katar.'),
  ('Fıkra kelimesinin Türkçede "güldürücü kısa öykücük (Nasrettin Hoca fıkraları vb.)" anlamı dışında edebiyat terimi olarak karşıladığı kavram hangisidir?', 'Gazete ve dergilerdeki güncel köşe yazısı', ['Kanonik kanun maddelerinin her bir bendi', 'İnsan omurgasını oluşturan kemik halkaları', 'Tiyatro oyunlarındaki perde arası müzikli bölüm'], 'Edebiyat incelemelerinde fıkra terimi, süreli yayınlardaki güncel köşe yazısı türünü ifade eder (hukukta madde bendi, anatomide omur anlamları terim dışı alanlardır).'),
  ('Montaigne\'in "Denemeler" adlı yapıtı ilk yayımlandığı dönemde toplam kaç kitaptan (ciltten) oluşacak biçimde son şeklini almıştır?', 'Üç kitap', ['Tek kitap', 'Yedi kitap', 'On iki kitap'], 'Montaigne 1580\'de ilk iki kitabı yayımlamış, 1588\'de üçüncü kitabı eklemiş ve ölümüne (1592) dek metin üzerinde eklemeler yapmıştır.'),
  ('Bir deneme metninde birinci tekil kişi ("ben") anlatımının sıkça tercih edilmesi aşağıdakilerden hangisinin doğal bir sonucudur?', 'Yazarın düşüncelerin sorumluluğunu kendi kişisel bakış açısıyla üstlenmesinin', ['Deneme yazarlarının dilbilgisi kuralları gereği çoğul ekleri kullanamamasının', 'Anlatılan olayların tümüyle yazarın çocukluk anılarından kopyalanmasının', 'Metnin yalnızca yazarın kendisi tarafından okunmak üzere kilitli tutulmasının'], 'Denemede nesnel bir otorite iddiası bulunmadığı için yazar, kendi gözlem ve düşüncelerini "ben" öznesiyle içtenlikle dile getirir.'),
  ('Deneme türünün konu alanı ile ilgili aşağıdaki yargılardan hangisi doğrudur?', 'İnsanı ve yaşamı ilgilendiren somut ya da soyut her konu denemenin konusu olabilir', ['Deneme yalnızca ölüm, kader ve tanrı gibi metafizik konuları işleyebilir', 'Denemede yalnızca edebiyat eserlerinin biçimsel kusurları ele alınabilir', 'Deneme güncel siyasal ve toplumsal konuların hiçbirine değinemez'], 'Aşk, dostluk, kitaplar, doğa, sanat, yalnızlık, uygarlık gibi insana dair her kavram denemenin özgürce işleyebileceği konulardır.'),
  ('Montaigne\'in "Denemeler"i hangi dilde kaleme alınmış ve o dilin düşünce düzyazısı olarak gelişimine büyük katkı sağlamıştır?', 'Fransızca', ['İngilizce', 'İtalyanca', 'Almanca'], 'Montaigne Latinceyi ana dili gibi bilmesine karşın eserini Fransızca yazmış ve Fransız düzyazısına esneklik ve düşünce derinliği kazandırmıştır.'),
  ('Aşağıdakilerden hangisi söyleşi (sohbet) türünün plan ve kurgu özelliklerinden biri değildir?', 'Giriş bölümünde kanıtlanacak bilimsel hipotezin matematiksel verilerle sunulması', ['Konuya dikkat çekici bir soru, anekdot veya güncel bir gözlemle girilmesi', 'Gelişme bölümünde içten bir konuşma üslubuyla düşüncelerin örneklendirilmesi', 'Sonuç bölümünde kesin bir kural dayatmadan düşündürücü bir etkiyle bitirilmesi'], 'Bilimsel hipotez ve matematiksel kanıtlama makale ve akademik tezlerin özelliğidir; söyleşide samimi ve serbest bir akış vardır.'),
  ('Gazete fıkralarının (köşe yazılarının) okuyucu tarafından kolayca okunabilmesi için dil ve anlatımının nasıl olması beklenir?', 'Açık, duru, akıcı ve güncel konuşma diline yakın olması', ['Soyut sembollerle örülü, kapalı ve şifreli bir şiir diline sahip olması', 'Yalnızca uzman hukukçuların ve ekonomistlerin anlayabileceği terimlerle yazılması', 'En az on beş-yirmi sayfa uzunluğunda ayrıntılı bölümlerden oluşması'], 'Gazete okuru farklı kültür düzeylerinden geldiği için fıkralar kısa, yalın, kıvrak ve kolay anlaşılır bir dille yazılır.'),
  ('Türk edebiyatında "Mavi ve Kara" denince Sabahattin Eyüboğlu akla gelirken, "Günlerin Getirdiği" denince ilk akla gelen yazarımız kimdir?', 'Nurullah Ataç', ['Suut Kemal Yetkin', 'Ahmet Rasim', 'Şevket Rado'], '"Günlerin Getirdiği" (1946), Nurullah Ataç\'ın en tanınmış ve Cumhuriyet dönemi denemeciliğinde çığır açmış yapıtıdır.'),
  ('"Bu Ülke", "Mağaradakiler", "Umrandan Uygarlığa" ve "Kırk Ambar" adlı düşünce ve deneme kitaplarının usta yazarı kimdir?', 'Cemil Meriç', ['Nermi Uygur', 'Salah Birsel', 'Şevket Rado'], 'Cemil Meriç; Doğu-Batı uygarlığı, Türk düşünce tarihi ve aydın sorunu üzerine yazdığı sarsıcı deneme ve incelemeleriyle tanınır.'),
  ('İstanbul\'un kahvehanelerini, Beyoğlu\'nu ve Boğaziçi kültürünü kendisiyle özdeşleşen neşeli, kıvrak ve alaycı bir dille anlatan, "Ah Beyoğlu Vah Beyoğlu" ve "Boğaziçi Şıngır Mıngır" adlı eserlerin deneme yazarı kimdir?', 'Salah Birsel', ['Ahmet Rasim', 'Suut Kemal Yetkin', 'Sabahattin Eyüboğlu'], 'Salah Birsel, tarihsel ve kültürel ayrıntıları kendine özgü esprili ve sözcük oyunlarıyla dolu deneme üslubuyla işlemiştir.'),
  ('Felsefe profesörü kimliğini edebiyat duyarlılığıyla birleştiren, "Dilin Gücü", "İnsan Açısından Edebiyat" ve "Güneşle" adlı eserleriyle tanınan deneme yazarımız kimdir?', 'Nermi Uygur', ['Cemil Meriç', 'Nurullah Ataç', 'Akşit Göktürk'], 'Nermi Uygur, felsefi kavramları günlük yaşam ve dil bilinciyle harmanlayan özgün Türkçe denemeleriyle öne çıkmıştır.'),
  ('Radyo konuşmaları ve gazete yazılarından doğan "Eşref Saat", "Ümit Dünyası" ve "Saadet Yolu" adlı kitaplarıyla söyleşi (sohbet) türünün Cumhuriyet dönemindeki en sevilen temsilcilerinden biri olan yazar kimdir?', 'Şevket Rado', ['Ahmet Rasim', 'Falih Rıfkı Atay', 'Refik Halit Karay'], 'Şevket Rado, iyimser ve yol gösterici üslubuyla radyo sohbetlerini ve köşe yazılarını kitaplaştırarak söyleşi türünün klasiklerini vermiştir.'),
  ('Servet-i Fünun döneminde bağımsız kalarak İstanbul\'un günlük yaşamını, sokaklarını ve geleneklerini fıkra ve söyleşi türlerinde ustalıkla anlatan, "Şehir Mektupları" ve "Eşkâl-i Zaman" adlı eserlerin yazarı kimdir?', 'Ahmet Rasim', ['Hüseyin Rahmi Gürpınar', 'Cenap Şahabettin', 'Süleyman Nazif'], 'Ahmet Rasim, Türk edebiyatında fıkra ve sohbet türlerinin ilk büyük ustalarından biri olup İstanbul folklorunu canlı bir dille kaydetmiştir.'),
  ('Aşağıdaki yazar-eser eşleştirmelerinden hangisi doğrudur?', 'Salah Birsel – Boğaziçi Şıngır Mıngır', ['Nurullah Ataç – Mağaradakiler', 'Nermi Uygur – Ramazan Sohbetleri', 'Ahmet Rasim – Kurutulmuş Felsefe Bahçesi'], '"Boğaziçi Şıngır Mıngır" Salah Birsel\'e aittir; Mağaradakiler Cemil Meriç\'in, Ramazan Sohbetleri Ahmet Rasim\'in, Kurutulmuş Felsefe Bahçesi ise yine Salah Birsel\'indir.'),
  ('Deneme, söyleşi ve fıkra türlerinin üçünün de edebiyat sınıflandırmasında içinde yer aldığı ana metin grubu aşağıdakilerden hangisidir?', 'Gazete ve dergi çevresinde gelişen öğretici metinler', ['Olay çevresinde gelişen kurmaca (anlatmaya bağlı) metinler', 'Göstermeye (sahnelemeye) bağlı dramatik metinler', 'Coşku ve heyecana bağlı ölçülü-uyaklı manzum metinler'], 'Makale, eleştiri, deneme, fıkra, söyleşi ve röportaj; gazete ve dergi çevresinde gelişen öğretici (düşünce) metinleri grubunda yer alır.'),
  ('Bir yazarın fıkra (köşe yazısı) yazarken ele aldığı iddiayı belgelerle, dipnotlarla ve laboratuvar deneyleriyle ispatlama zorunluluğunun bulunmaması, fıkrayı hangi türden ayırır?', 'Makaleden', ['Söyleşiden', 'Denemeden', 'Anıdan'], 'Makale türünde ileri sürülen savın bilimsel veriler, belgeler ve kanıtlarla ispatlanması zorunluyken; fıkra, söyleşi ve denemede kanıtlama zorunluluğu yoktur.'),
  ('"Şehir Mektupları", "Eşkâl-i Zaman", "Cidd ü Mizah", "Gülüp Ağladıklarım" ve "Muharrir Bu Ya" adlı eserlerin tümü hangi yazarımıza aittir?', 'Ahmet Rasim', ['Şevket Rado', 'Salah Birsel', 'Falih Rıfkı Atay'], 'Sayılan yapıtların tamamı fıkra, söyleşi ve anı türlerinin usta kalemi Ahmet Rasim\'in tanınmış eserleridir.'),
  ('Şevket Rado\'nun "İnsan Severse Yaşar" ve "Saadet Yolu" adlı yapıtları edebiyatımızda hangi türün karakteristik örnekleri arasında incelenir?', 'Söyleşi', ['Destan', 'Biyografi', 'Röportaj'], 'Şevket Rado\'nun Eşref Saat, Ümit Dünyası, Hayat Böyledir, Aile Sohbetleri, Saadet Yolu ve İnsan Severse Yaşar kitapları söyleşi türünün tanınmış örnekleridir.'),
  ('Aşağıdakilerden hangisi iyi bir deneme yazarında bulunması beklenen temel niteliklerden biri değildir?', 'Okuyucuya kendi görüşlerini tek mutlak doğru olarak zorla kabul ettirme hırsı', ['Zengin bir okuma kültürü, gözlem gücü ve bağımsız düşünebilme yetisi', 'Dilin inceliklerine hâkimiyet ve kendine özgü, içten bir üslup yaratabilme becerisi', 'Kavramlara alışılmış kalıpların dışından, sorgulayıcı bir gözle bakabilme duyarlılığı'], 'Deneme yazarı kendi düşüncesini içtenlikle paylaşır ancak dogmatik bir dayatma veya mutlak doğruluk iddiası taşımaz.'),
  ('Türk edebiyatında "Ah Beyoğlu Vah Beyoğlu" ve "Kahveler Kitabı" adlı sevilen deneme yapıtları hangi yazarımızın kaleminden çıkmıştır?', 'Salah Birsel', ['Sabahattin Eyüboğlu', 'Suut Kemal Yetkin', 'Nermi Uygur'], 'Her iki eser de Salah Birsel\'in edebiyat mahfillerini ve İstanbul kültürünü anlattığı ünlü deneme kitaplarıdır.'),
  ('"Mavi ve Kara" Sabahattin Eyüboğlu\'nun, "Bu Ülke" Cemil Meriç\'in, "Dilin Gücü" ise Nermi Uygur\'un hangi edebi türdeki başyapıtlarıdır?', 'Deneme', ['Tiyatro', 'Roman', 'Destan'], 'Üç yapıt da Cumhuriyet dönemi Türk edebiyatında farklı düşünce damarlarını temsil eden klasikleşmiş deneme kitaplarıdır.'),
  ('Dünya edebiyatında Montaigne ve Francis Bacon ile başlayan deneme geleneğinin Türk edebiyatındaki önemli temsilcileri arasında aşağıdakilerden hangisi yer almaz?', 'Ömer Seyfettin', ['Nurullah Ataç', 'Sabahattin Eyüboğlu', 'Nermi Uygur'], 'Ömer Seyfettin, Milli Edebiyat döneminde olay öykücülüğünün (Maupassant tarzı hikâyenin) kurucu ustasıdır; Ataç, Eyüboğlu ve Uygur ise deneme yazarlarımızdır.'),
  ('Divan edebiyatında gezilip görülen yerlerin doğasını, toplumsal yaşamını ve geleneklerini anlatan gezi türündeki eserlere verilen genel ad nedir?', 'Seyahatname', ['Siyasetname', 'Fütüvvetname', 'Pendname'], 'Klasik Türk edebiyatında gezi yazısı niteliği taşıyan yapıtlara seyahatname adı verilir.'),
  ('Gezi yazısı türünün öğretici metinler içerisindeki temel işlevi aşağıdakilerden hangisidir?', 'Gezilip görülen yerleri okuyucuya tanıtmak ve gözlemleri aktarmak', ['Toplumsal sorunlara kesin ve değişmez yasalarla çözüm üretmek', 'Bireyin iç dünyasındaki bilinçaltı çatışmalarını kurgusal olarak işlemek', 'Tarihsel olayları kronolojik sırayla ve resmi belgelere dayalı kanıtlamak'], 'Gezi yazıları, yazarın gördüğü coğrafyaları gözlem gücüyle okura tanıttığı öğretici metinlerdir.'),
  ('13. yüzyılda Venedik\'ten yola çıkarak İpek Yolu üzerinden Çin\'e kadar uzanan seyahatleriyle tanınan ünlü İtalyan gezgin kimdir?', 'Marco Polo', ['Kristof Kolomb', 'Vasco da Gama', 'Ferdinand Macellan'], 'Marco Polo, Kubilay Han\'ın sarayında yıllarca bulunmuş ve Doğu dünyasını Avrupa\'ya tanıtmıştır.'),
  ('14. yüzyılda Kuzey Afrika\'dan başlayarak Anadolu, Orta Asya, Hindistan ve Çin\'e kadar uzanan yolculuklar yapan ünlü Faslı gezgin kimdir?', 'İbn Battuta', ['İbn Haldun', 'İbn Sina', 'İbn Rüşd'], 'Tancalı İbn Battuta, Orta Çağ İslam dünyasının en büyük seyyahı kabul edilir.'),
  ('Türk edebiyatında anı (hatırat) türünün ilk büyük ve özgün örneği kabul edilen "Babürname" adlı eserin yazarı kimdir?', 'Babürşah', ['Ali Şir Nevai', 'Hüseyin Baykara', 'Uluğ Bey'], 'Hindistan\'da Babür İmparatorluğu\'nu kuran Zahirüddin Muhammed Babür, kendi yaşamını ve seferlerini Babürname\'de anlatmıştır.'),
  ('Türk edebiyatında ilk gezi yazısı (seyahatname) örneği kabul edilen "Mir\'atü\'l-Memalik" adlı eserin yazarı kimdir?', 'Seydi Ali Reis', ['Piri Reis', 'Katip Çelebi', 'Evliya Çelebi'], '16. yüzyıl Osmanlı denizcisi Seydi Ali Reis, Hindistan\'dan İstanbul\'a dönüş yolculuğunu Mir\'atü\'l-Memalik\'te anlatmıştır.'),
  ('Seydi Ali Reis\'in gezi türündeki ünlü eseri "Mir\'atü\'l-Memalik"in günümüz Türkçesindeki kelime anlamı nedir?', 'Memleketlerin Aynası', ['Denizlerin Kitabı', 'Yolcuların Rehberi', 'İklimlerin Haritası'], 'Mir\'at "ayna", memalik ise "memleketler, ülkeler" anlamına gelir; eser "Memleketlerin Aynası" demektir.'),
  ('17. yüzyılda elli yılı aşkın süre Osmanlı coğrafyasını ve komşu ülkeleri dolaşarak on ciltlik dev bir "Seyahatname" yazan gezginimiz kimdir?', 'Evliya Çelebi', ['Naima Efendi', 'Yirmisekiz Çelebi Mehmet', 'Ahmet Resmi Efendi'], 'Evliya Çelebi, Türk ve dünya gezi edebiyatının en hacimli ve renkli yapıtlarından birini ortaya koymuştur.'),
  ('Evliya Çelebi\'nin seyahatlere çıkmasına vesile olan ünlü rüyasında Hz. Muhammed\'den heyecanla "Şefaat ya Resulallah" yerine ne dilediği anlatılır?', 'Seyahat ya Resulallah', ['İlim ya Resulallah', 'Zafer ya Resulallah', 'Devlet ya Resulallah'], 'Evliya Çelebi, İstanbul\'daki Ahi Çelebi Camii\'nde gördüğü rüyada dil sürçmesiyle "Seyahat ya Resulallah" dediğini ve gezilerinin böyle başladığını aktarır.'),
  ('Servetifünun edebiyatının önde gelen şairlerinden olup gezi yazısı türünde modern ve sanatsal örnekler veren "Hac Yolunda" adlı eserin yazarı kimdir?', 'Cenap Şahabettin', ['Tevfik Fikret', 'Mehmet Rauf', 'Hüseyin Cahit Yalçın'], 'Cenap Şahabettin, şiirlerinin yanı sıra güçlü üslubuyla yazdığı gezi kitaplarıyla Türk edebiyatında çığır açmıştır.'),
  ('Cumhuriyet dönemi Türk edebiyatında gezi yazısı ve anı türlerinin en üretken ve usta kalemlerinden biri olan "Denizaşırı" ve "Çankaya" yazarımız kimdir?', 'Falih Rıfkı Atay', ['Reşat Nuri Güntekin', 'Nurullah Ataç', 'Suut Kemal Yetkin'], 'Falih Rıfkı Atay, sağlam ve kıvrak Türkçesiyle Cumhuriyet devri gezi ve hatırat edebiyatının zirve isimlerindendir.'),
  ('Bir yazarın yaşadığı ya da tanık olduğu önemli olayları üzerinden belli bir zaman geçtikten sonra belleğine ve belgelere dayanarak anlattığı yazı türüne ne ad verilir?', 'Anı (Hatırat)', ['Günlük (Günce)', 'Fıkra (Köşe yazısı)', 'Deneme'], 'Yaşanmış olayların zaman geçtikten sonra geriye dönük bir bakışla kaleme alınması anı (hatırat) türünü oluşturur.'),
  ('8. yüzyılda dikilen ve Bilge Kağan ile Kültigin\'in Türk milletine hesap verircesine geçmiş seferleri ve olayları anlattığı hangi eserimiz anı ve söylev türünün ilk izlerini taşır?', 'Orhun Yazıtları', ['Dede Korkut Hikayeleri', 'Kutadgu Bilig', 'Atabetü\'l-Hakayık'], 'Göktürk (Orhun) Yazıtları, hükümdarların yaşadıkları tarihsel olayları kendi ağızlarından aktarması bakımından anı ve hitabetin Türk edebiyatındaki ilk örneklerindendir.'),
  ('Reşat Nuri Güntekin\'in Milli Eğitim Müfettişi olarak yıllarca dolaştığı Anadolu kasaba ve şehirlerindeki izlenimlerini topladığı ünlü gezi kitabı hangisidir?', 'Anadolu Notları', ['Çalıkuşu', 'Yaprak Dökümü', 'Miskinler Tekkesi'], 'Reşat Nuri Güntekin, Anadolu yollarındaki hanları, tiyatroları ve insan manzaralarını "Anadolu Notları" adlı iki ciltlik gezi eserinde yalın bir dille anlatmıştır.'),
  ('Bir kimsenin kendi yaşam öyküsünü bizzat kendisinin kaleme aldığı yazılara "otobiyografi" denirken, anı türünün otobiyografiden ayrılan en önemli yönü nedir?', 'Otobiyografinin yalnızca yazarın kendi yaşam çizgisine odaklanması, anının ise tanık olunan dış olayları ve çağdaş kişileri de genişçe kuşatması', ['Otobiyografinin her zaman başkası tarafından yazılması, anının ise yalnızca imzasız yayımlanması', 'Otobiyografide doğum tarihinin gizlenmesi, anıda ise sadece gelecekteki hayallerin anlatılması', 'Otobiyografinin yalnızca şiir biçiminde, anının ise yalnızca mektup biçiminde kaleme alınması'], 'Otobiyografide merkezde sadece yazarın öz yaşamı varken, anıda yazarın tanıklık ettiği dönem, çevre ve tarihsel şahsiyetler ön plana çıkar.'),
  ('Türk edebiyatında "Mavi Yolculuk" kavramını kitaplaştırarak Ege ve Akdeniz kıyılarının tarihsel-mitolojik zenginliğini tanıtan hümanist yazar ve çevirmen kimdir?', 'Azra Erhat', ['Adalet Ağaoğlu', 'Sevgi Soysal', 'Tomris Uyar'], 'Klasik filolog ve çevirmen Azra Erhat, "Mavi Yolculuk" adlı gezi kitabıyla Anadolu\'nun antik kıyı kültürünü edebiyatımıza kazandırmıştır.'),
  ('Servetifünun romanının büyük ustası Halit Ziya Uşaklıgil\'in çocukluğundan Meşrutiyet yıllarına kadarki edebi ve sosyal yaşamını anlattığı beş ciltlik ünlü anı eseri hangisidir?', 'Kırk Yıl', ['Saray ve Ötesi', 'Edebi Hatıralar', 'Zeytindağı'], 'Halit Ziya Uşaklıgil\'in "Kırk Yıl" adlı dev eseri, hem yazarın yaşamına hem de Servetifünun döneminin edebi ortamına ışık tutan temel bir hatırattır.'),
  ('Milli Edebiyat ve Cumhuriyet döneminin büyük romancısı Yakup Kadri Karaosmanoğlu\'nun Kurtuluş Savaşı yıllarındaki gözlem ve hatıralarını topladığı anı kitabı hangisidir?', 'Vatan Yolunda', ['Zoraki Diplomat', 'Anamın Kitabı', 'Politikada 45 Yıl'], 'Yakup Kadri Karaosmanoğlu, Milli Mücadele sürecinde İstanbul ve Ankara\'daki tanıklıklarını "Vatan Yolunda" adlı anı eserinde anlatmıştır.'),
  ('Yakup Kadri Karaosmanoğlu\'nun Tiran, Prag, Lahey, Bern ve Tahran\'da elçilik yaptığı yıllara ilişkin anılarını esprili ve eleştirel bir dille anlattığı eseri hangisidir?', 'Zoraki Diplomat', ['Sefaretname', 'Avrupa Mektupları', 'Yaban'], 'Kadro dergisinin kapanmasının ardından yurt dışına elçi olarak atanan Yakup Kadri, bu süreci "Zoraki Diplomat" adlı ünlü anı kitabında işlemiştir.'),
  ('Halide Edip Adıvar\'ın Kurtuluş Savaşı\'nda cephede onbaşı ve çavuş rütbeleriyle bizzat yaşadığı mücadele yıllarını anlattığı ünlü anı eseri hangisidir?', 'Türk\'ün Ateşle İmtihanı', ['Mor Salkımlı Ev', 'Sinekli Bakkal', 'Vurun Kahpeye'], 'Halide Edip, İstanbul\'dan Anadolu\'ya geçişini, Sultanahmet mitinglerini ve Batı Cephesi\'ndeki tanıklıklarını "Türk\'ün Ateşle İmtihanı"nda anlatmıştır.'),
  ('Halide Edip Adıvar\'ın doğup büyüdüğü Beşiktaş\'taki konaktan başlayarak 1918 yılına kadarki çocukluk, gençlik ve eğitim hayatını anlattığı anı kitabı hangisidir?', 'Mor Salkımlı Ev', ['Anamın Kitabı', 'Kırk Yıl', 'Handan'], '"Mor Salkımlı Ev", yazarın çocukluk dünyasını, geleneksel Osmanlı aile yaşamını ve Suriye\'deki eğitim çalışmalarını duygulu bir dille aktarır.'),
  ('Abdülhak Şinasi Hisar\'ın çocukluk ve gençlik yıllarındaki İstanbul yalılarını, köşklerini ve kaybolan yaşam kültürünü anı tadında anlattığı eseri hangisidir?', 'Boğaziçi Mehtapları', ['Hac Yolunda', 'Zeytindağı', 'Frankfurt Seyahatnamesi'], 'Abdülhak Şinasi Hisar; "Boğaziçi Mehtapları", "Boğaziçi Yalıları" ve "Geçmiş Zaman Köşkleri"nde maziye duyduğu özlemi anı-izlenim üslubuyla dile getirmiştir.'),
  ('Cumhuriyet döneminde Yedi Meşaleciler topluluğunun kuramcısı Yaşar Nabi Nayır\'ın Balkan ülkelerine yaptığı yolculuğu anlattığı gezi eseri ile aynı dönemde Bedri Rahmi Eyüboğlu\'nun Anadolu gezilerini ressam duyarlılığıyla aktardığı eseri hangisidir?', 'Canım Anadolu', ['Bizim Akdeniz', 'Suriye Mektupları', 'Hac Yolunda'], 'Ressam ve şair Bedri Rahmi Eyüboğlu, "Canım Anadolu" ve "Tezek" gibi kitaplarında Anadolu insanını ve doğasını renkli gezi-deneme yazılarıyla anlatmıştır.'),
  ('Aşağıdaki yapıtlardan hangisi edebi türü bakımından diğer üçünden farklıdır?', 'Çankaya', ['Hac Yolunda', 'Avrupa Mektupları', 'Mir\'atü\'l-Memalik'], 'Hac Yolunda, Avrupa Mektupları ve Mir\'atü\'l-Memalik gezi yazısı (seyahatname) türündeyken, Falih Rıfkı Atay\'ın "Çankaya"sı anı (hatırat) türündedir.'),
  ('Bir gezi yazarının gezdiği yabancı ülkedeki gelenekleri kendi ülkesindeki geleneklerle kıyaslayarak anlatması metinde hangi düşünceyi geliştirme yolunun kullanıldığını gösterir?', 'Karşılaştırma', ['Tanık gösterme', 'Sayısal verilerden yararlanma', 'Soyutlama'], 'İki farklı coğrafya, kültür veya toplum arasındaki benzerlik ve farklılıkların ortaya konulması karşılaştırma yöntemidir.'),
  ('Babürşah\'ın 1526 yılında Panipat Savaşı\'nı kazanarak kurduğu ve anılarında doğasını, muson yağmurlarını, meyvelerini uzun uzun anlattığı imparatorluk hangi ülkede kurulmuştur?', 'Hindistan', ['Mısır', 'Macaristan', 'İspanya'], 'Babürşah, Kuzey Hindistan\'a hakim olarak Babür (Gürkanlı) İmparatorluğu\'nu kurmuş ve Babürname\'nin önemli bir kısmını Hindistan\'a ayırmıştır.'),
  ('Aşağıdakilerden hangisi iyi bir gezi yazısında bulunması gereken niteliklerden biri değildir?', 'Okuru etkilemek için coğrafi ve tarihi gerçekleri kasıtlı olarak çarpıtmak', ['Görülen yerlerin ilginç ve özgün yönlerini seçici bir gözlemle yakalamak', 'Akıcı, canlı ve okurda görme isteği uyandıran bir dil kullanmak', 'İnsanların yaşayış biçimlerini önyargısız ve kültürlü bir bakışla aktarmak'], 'Gezi yazısında yazar öznel izlenimlerini katabilir ancak maddi, tarihi ve coğrafi olguları kasıtlı biçimde çarpıtmaması gerekir.'),
  ('Gezi yazısı türünde gezginin (seyyahın) en temel bilgi toplama aracı aşağıdakilerden hangisidir?', 'Gözlem', ['Laboratuvar deneyi', 'Mahkeme tutanağı', 'Kurgusal rüya'], 'Gezi edebiyatının omurgasını yazarın dış dünyaya yönelttiği dikkatli, meraklı ve seçici gözlem gücü oluşturur.'),
  ('Türk edebiyatında bilinen ilk şairler tezkiresi olarak kabul edilen "Mecâlisü\'n-Nefâis" adlı eserin yazarı aşağıdakilerden hangisidir?', 'Ali Şir Nevaî', ['Kâşgarlı Mahmud', 'Yusuf Has Hacib', 'Hoca Ahmed Yesevî'], 'Mecâlisü\'n-Nefâis, Çağatay sahasının büyük şairi Ali Şir Nevaî tarafından 15. yüzyılda yazılmış ilk Türk tezkiresidir.'),
  ('Anadolu sahasında kaleme alınan ilk şairler tezkiresi olan "Heşt Behişt" kimin eseridir?', 'Sehî Bey', ['Latîfî Çelebi', 'Âşık Çelebi', 'Kınalızâde Hasan Çelebi'], 'Sehî Bey, 1538 yılında tamamladığı "Heşt Behişt" (Sekiz Cennet) adlı eseriyle Anadolu sahasında ilk tezkire yazarımız olmuştur.'),
  ('Mustafa Kemal Atatürk\'ün hayatını ve dönemin tarihsel koşullarını üç cilt hâlinde anlatan "Tek Adam" adlı biyografik eserin yazarı kimdir?', 'Şevket Süreyya Aydemir', ['Falih Rıfkı Atay', 'Yakup Kadri Karaosmanoğlu', 'Ruşen Eşref Ünaydın'], 'Şevket Süreyya Aydemir, Atatürk biyografisi olan üç ciltlik "Tek Adam" eseriyle Cumhuriyet dönemi biyografi türüne damga vurmuştur.'),
  ('Oğuz Atay\'ın "Bir Bilim Adamının Romanı" adlı biyografik romanında hayatı anlatılan ünlü bilim insanı ve üniversite hocası kimdir?', 'Mustafa İnan', ['Cahit Arf', 'Feza Gürsey', 'Oktay Sinanoğlu'], 'Oğuz Atay, İTÜ İnşaat Fakültesi\'ndeki hocası Prof. Dr. Mustafa İnan\'ın yaşam öyküsünü "Bir Bilim Adamının Romanı" adıyla kaleme almıştır.'),
  ('Divan edebiyatında şairlerin hayat hikâyelerini, sanat anlayışlarını ve şiirlerinden örnekleri bir araya getiren eserlere ne ad verilir?', 'Tezkire', ['Sefaretname', 'Surname', 'Fütüvvetname'], 'Tezkireler (tezkiretü\'ş-şuarâ), klasik Türk edebiyatında günümüzdeki biyografik antolojilerin karşılığı olan temel eserlerdir.'),
  ('Şevket Süreyya Aydemir\'in İsmet İnönü\'nün yaşamını ve siyasi mücadelesini merkeze alarak yazdığı üç ciltlik biyografik eseri hangisidir?', 'İkinci Adam', ['Suyu Arayan Adam', 'Menderes\'in Dramı', 'Makedonya\'dan Ortaasya\'ya Enver Paşa'], 'Şevket Süreyya Aydemir, Atatürk\'ü anlattığı "Tek Adam"dan sonra İsmet İnönü\'nün hayatını ve dönemini "İkinci Adam" adıyla kaleme almıştır.'),
  ('Şevket Süreyya Aydemir\'in kendi yaşam öyküsünü ve düşünsel serüvenini anlattığı otobiyografik nitelikteki ünlü eseri hangisidir?', 'Suyu Arayan Adam', ['Toprak Uyanırsa', 'Kahramanlar Doğmalıydı', 'İhtilalin Mantığı'], '"Suyu Arayan Adam", Şevket Süreyya Aydemir\'in Turancılıktan sosyalizme ve Kemalizme uzanan kendi hayat ve fikir yolculuğunu anlatan otobiyografisidir.'),
  ('Bir kimsenin kendi yaşam öyküsünü bizzat kendisinin kaleme aldığı edebî türe ne ad verilir?', 'Otobiyografi', ['Biyografi', 'Monografi', 'Bibliyografya'], 'Kişinin kendi hayatını birinci tekil kişi ağzıyla ve öznel-belgesel bir bakışla anlattığı yazı türü otobiyografidir (öz yaşam öyküsü).'),
  ('Ali Şir Nevaî, "Mecâlisü\'n-Nefâis" adlı tezkiresini hangi Türk lehçesiyle kaleme almıştır?', 'Çağatay Türkçesi', ['Eski Anadolu Türkçesi', 'Karahanlı Türkçesi', 'Kıpçak Türkçesi'], '15. yüzyıl Herat kültür çevresinin en büyük temsilcisi olan Ali Şir Nevaî, "Mecâlisü\'n-Nefâis"i Çağatay Türkçesiyle yazmıştır.'),
  ('Sehî Bey\'in Anadolu sahasındaki ilk tezkire olan eserine verdiği "Heşt Behişt" adının Türkçe anlamı nedir?', 'Sekiz Cennet', ['Yedi İklim', 'Dokuz Felek', 'Dört Mevsim'], 'Farsça "heşt" (sekiz) ve "behişt" (cennet) kelimelerinden oluşan "Heşt Behişt", sekiz tabaka (bölüm) hâlinde düzenlendiği için "Sekiz Cennet" adını taşır.'),
  ('Alanında ün yapmış sanat, bilim, siyaset veya spor insanlarının hayatlarını belgelere dayanarak nesnel bir tutumla anlatan edebî tür hangisidir?', 'Biyografi', ['Otobiyografi', 'Günlük', 'Deneme'], 'Biyografi (yaşam öyküsü), tanınmış kişilerin hayatlarını üçüncü kişi anlatımıyla, bilgi ve belgelere dayalı olarak aktaran öğretici metin türüdür.'),
  ('Cumhuriyet dönemi Türk edebiyatında öz yaşam öyküsü (otobiyografi) kavramını karşılamak üzere Nurullah Ataç ve çağdaşlarınca önerilen Türkçe terim hangisidir?', 'Öz yaşam öyküsü', ['Yaşam öyküsü', 'İç dökümü', 'Gezi yazısı'], 'Batı kökenli "otobiyografi" terimine karşılık Türkçede "öz yaşam öyküsü", "biyografi"ye karşılık ise "yaşam öyküsü" terimi yerleşmiştir.'),
  ('Osmanlı İmparatorluğu\'nda şeyhülislamların, müderrislerin ve âlimlerin biyografilerini bir araya getiren Taşköprülüzâde\'nin ünlü Arapça eseri "eş-Şekâiku\'n-Nu\'mâniyye"yi Türkçeye tercüme ve zeyl eden kimdir?', 'Mecdî Mehmed Efendi', ['Kâtip Çelebi', 'Naimâ Efendi', 'Evliya Çelebi'], 'Edirneli Mecdî Mehmed Efendi, "Hadâiku\'ş-Şekâik" adıyla bu dev ulema biyografisini genişleterek Türkçeye kazandırmıştır.'),
  ('Peyami Safa\'nın kendi çocukluk hastalıklarından ve yaşam deneyimlerinden derin izler taşıyan otobiyografik romanı aşağıdakilerden hangisidir?', 'Dokuzuncu Hariciye Koğuşu', ['Fatih-Harbiye', 'Sözde Kızlar', 'Yalnızız'], 'Kemik veremi hastalığı nedeniyle hastanelerde geçen çocukluğunu "Dokuzuncu Hariciye Koğuşu"na taşıyan Peyami Safa, Türk edebiyatının en güçlü otobiyografik romanlarından birini yazmıştır.'),
  ('Orhan Kemal\'in kendi gençlik yıllarını, Adana\'daki ve Beyrut\'taki yaşam mücadelesini otobiyografik bir çizgide anlattığı "Baba Evi" adlı romanının devamı niteliğindeki eseri hangisidir?', 'Avare Yıllar', ['Bereketli Topraklar Üzerinde', 'Murtaza', 'Eskici ve Oğulları'], 'Orhan Kemal, "Baba Evi" ve onun devamı olan "Avare Yıllar" gibi romanlarında kendi çocukluk ve ilk gençlik yıllarını otobiyografik gerçeklikle yansıtmıştır.'),
  ('Yaşar Kemal\'in kendi yaşam öyküsünü, çocukluğunu ve edebiyat serüvenini gazeteci Alain Bosquet ile yaptığı nehir söyleşiler üzerinden anlattığı otobiyografik nitelikli kitap hangisidir?', 'Yaşar Kemal Kendini Anlatıyor', ['İnce Memed', 'Üç Anadolu Efsanesi', 'Çukurova Yana Yana'], 'Alain Bosquet\'nin sorularıyla şekillenen "Yaşar Kemal Kendini Anlatıyor", büyük romancımızın çocukluğundan sanat anlayışına uzanan temel öz yaşam kaynağıdır.'),
  ('Cevat Şakir Kabaağaçlı\'nın (Halikarnas Balıkçısı) Bodrum\'a sürgün edilişini ve orada yeni bir kimlik buluşunu anlattığı otobiyografik ve anı niteliğindeki ünlü eseri hangisidir?', 'Mavi Sürgün', ['Aganta Burina Burinata', 'Ötelerin Çocuğu', 'Uluç Reis'], '"Mavi Sürgün", Cevat Şakir Kabaağaçlı\'nın İstiklal Mahkemesi kararıyla Bodrum\'a sürülmesini ve Halikarnas Balıkçısı\'na dönüşümünü anlatan otobiyografik başyapıtıdır.'),
  ('Yazarın kendi hayatını anlatırken hafızasına, mektuplarına, günlüklerine ve aile büyüklerinden dinlediklerine başvurması hangi türün temel çalışma yöntemidir?', 'Otobiyografi', ['Tezkire', 'Masal', 'Destan'], 'Otobiyografi yazarı, kendi geçmişini kurgularken bellek verilerini mektup, günlük ve aile tanıklıklarıyla birleştirir.'),
  ('Aşağıdaki eser-yazar eşleştirmelerinden hangisi biyografi ve tezkire edebiyatımız açısından doğrudur?', 'Heşt Behişt - Sehî Bey', ['Mecâlisü\'n-Nefâis - Latîfî', 'Tek Adam - Oğuz Atay', 'Bir Bilim Adamının Romanı - Şevket Süreyya Aydemir'], '"Heşt Behişt" Sehî Bey\'e, "Mecâlisü\'n-Nefâis" Ali Şir Nevaî\'ye, "Tek Adam" Şevket Süreyya Aydemir\'e, "Bir Bilim Adamının Romanı" Oğuz Atay\'a aittir.'),
  ('İslam kültür ve edebiyatında Hz. Muhammed\'in fiziksel ve ahlaki güzelliklerini manzum veya mensur olarak betimleyen portre nitelikli eserlere ne ad verilir?', 'Hilye', ['Sûrname', 'Maktel', 'Pendname'], 'Hilye (Hilye-i Şerîf), başta Hâkânî Mehmed Bey\'in eseri olmak üzere klasik edebiyatımızda Hz. Peygamber\'in maddi ve manevi portresini çizen türdür.'),
  ('Türk edebiyatında edebî mektup türünün en ünlü klasik örneği sayılan ve "Selâm verdim rüşvet değildir deyü almadılar" sözüyle tanınan "Şikâyetname" kimin eseridir?', 'Fuzûlî', ['Bâkî', 'Nedim', 'Nef\'î'], '16. yüzyıl divan şairi Fuzûlî, kendisine bağlanan dokuz akçelik maaşı alamaması üzerine Nişancı Celâlzâde Mustafa Çelebi\'ye ünlü "Şikâyetname" mektubunu yazmıştır.'),
  ('Cahit Sıtkı Tarancı\'nın çocukluk ve okul arkadaşı olan hangi ünlü şaire yazdığı mektuplar "Ziya\'ya Mektuplar" adıyla kitaplaştırılmıştır?', 'Ziya Osman Saba', ['Ziya Gökalp', 'Yusuf Ziya Ortaç', 'Ziya Paşa'], 'Cahit Sıtkı Tarancı\'nın yakın dostu ve şair arkadaşı Ziya Osman Saba\'ya 1930-1946 yılları arasında gönderdiği mektuplar "Ziya\'ya Mektuplar" adıyla yayımlanmıştır.'),
  ('Divan edebiyatı döneminde hem özel hem resmi mektupları ve süslü düzyazı örneklerini bir araya getiren kitaplara ne ad verilirdi?', 'Münşeat', ['Tezkire', 'Sefaretname', 'Kıyafetname'], 'Klasik Türk edebiyatında mektup yazma sanatına "inşâ", mektup yazan ustalara "münşî", mektupların toplandığı mecmualara ise "münşeat" denirdi.'),
  ('Divan edebiyatı döneminde günü gününe tutulan notları, saray ve sefer kayıtlarını içeren ve modern günlüğün karşılığı olan eserlere ne ad verilirdi?', 'Rûznâme', ['Menâkıbname', 'Gazavatname', 'Fütüvvetname'], 'Farsça "rûz" (gün) ve "nâme" (yazı/mektup) kelimelerinden oluşan "rûznâme", Osmanlı kültüründe günlük türünün tarihsel karşılığıdır.'),
  ('Nazım Hikmet\'in Bursa Cezaevinde yatarken genç şair ve ressam dostuna yazdığı sanat, şiir ve yaşam üzerine mektupları hangi adla yayımlanmıştır?', 'Kemal Tahir\'e Mahpusaneden Mektuplar', ['Ziya\'ya Mektuplar', 'Limni ve Malta Mektupları', 'Kültür Üzerine Mektuplar'], 'Nazım Hikmet\'in hem Kemal Tahir\'e ("Kemal Tahir\'e Mahpusaneden Mektuplar") hem de Orhan Kemal, Va-Nu ve Piraye\'ye yazdığı mektuplar mektup edebiyatımızın başyapıtlarıdır.'),
  ('Nazım Hikmet\'in büyük aşkı ve eşi Hatice Piraye Altınoğlu\'na hapishanelerden gönderdiği duygu ve düşünce yüklü mektupları hangi başlıkla kitaplaşmıştır?', 'Piraye\'ye Mektuplar', ['Memet Fuat\'a Mektuplar', 'Bursa\'dan Mektuplar', 'Münevver\'e Mektuplar'], 'Nazım Hikmet\'in yıllar süren mahpusluk döneminde eşi Piraye\'ye yazdığı mektuplar "Piraye\'ye Mektuplar" (iki cilt) adıyla Türk mektup edebiyatında önemli yer tutar.'),
  ('Tomris Uyar\'ın 1975 yılından itibaren yayımlamaya başladığı ve edebiyat dünyamızın tanıklığını da içeren ünlü günlük dizisinin genel üst başlığı nedir?', 'Gündökümü', ['Kuşları Örtünmek', 'Uçuş Günlüğü', 'Yolculuk Defteri'], 'Öykücü ve çevirmen Tomris Uyar, "Gündökümü" ortak üst başlığı altında ("Sesler, Yüzler, Sokaklar", "Günlerin Tortusu" vb.) günlüklerini bir araya getirmiştir.'),
  ('Deneme ve günlük türünün usta kalemi Salah Birsel\'in ilk günlük kitabı olan ve edebiyat çevrelerindeki izlenimlerini yansıtan 1955 tarihli eseri hangisidir?', 'Günlük', ['Boğaziçi Şıngır Mıngır', 'Ah Beyoğlu Vah Beyoğlu', 'Kahveler Kitabı'], 'Salah Birsel\'in 1955\'te yayımlanan "Günlük" adlı eseri, Cumhuriyet döneminde doğrudan bu başlığı taşıyan ve günlük türünü bağımsızlaştıran öncü kitaplardandır.'),
  ('Bir kimsenin gördüklerini, yaşadıklarını, duygu ve düşüncelerini günü gününe, tarih belirterek ve birinci tekil kişi ağzıyla kaleme aldığı edebî tür hangisidir?', 'Günlük (Günce)', ['Anı (Hatıra)', 'Otobiyografi', 'Gezi yazısı'], 'Günlük (günce), olaylar henüz sıcaklığını korurken tarih atılarak günü gününe yazılan, samimi ve içe dönük anlatı türüdür.'),
  ('Aralarında mesafe bulunan kişi ya da kurumların haberleşmek, duygu ve düşüncelerini paylaşmak veya edebi-felsefi konuları tartışmak amacıyla yazdıkları metin türü hangisidir?', 'Mektup', ['Tutanak', 'Fıkra', 'Söyleşi'], 'Mektup; özel, edebi, resmi ve iş mektupları gibi alt dalları bulunan, hitap sözüyle başlayıp tarih ve imzayla biten köklü bir iletişim ve edebiyat türüdür.'),
  ('Oğuz Atay\'ın 1970-1977 yılları arasında tuttuğu, roman projelerini, sanat sancılarını ve hastalığıyla mücadelesini anlattığı eseri ölümünden sonra hangi adla yayımlanmıştır?', 'Günlük', ['Korkuyu Beklerken', 'Eylembilim', 'Oyunlarla Yaşayanlar'], 'Oğuz Atay\'ın vefatından sonra yakın dostlarınca yayıma hazırlanan "Günlük", yazarın iç dünyasını ve "Türkiye\'nin Ruhu" gibi tasarılarını aydınlatan eşsiz bir kaynaktır.'),
  ('Ziya Gökalp\'in Birinci Dünya Savaşı sonrasında İngilizler tarafından sürgüne gönderildiği adalardan ailesine (eşi Vecihe Hanım ile kızları Seniha, Hürriyet ve Türkan\'a) yazdığı mektuplar hangi adla toplanmıştır?', 'Limni ve Malta Mektupları', ['Avrupa Mektupları', 'İngiliz Mektupları', 'Gurbet Mektupları'], 'Ziya Gökalp\'in sürgün yıllarında eşine ve kızlarına yazdığı felsefi, ahlaki ve sevgi dolu mektuplar "Limni ve Malta Mektupları" adıyla yayımlanmıştır.'),
  ('Halide Edib Adıvar\'ın 1901 yılında yayımlanan ve mektup-roman tekniğinin Türk edebiyatındaki en başarılı ilk örneklerinden kabul edilen eseri hangisidir?', 'Handan', ['Ateşten Gömlek', 'Sinekli Bakkal', 'Vurun Kahpeye'], 'Halide Edib Adıvar\'ın "Handan" romanı, kahramanların birbirlerine yazdıkları mektuplardan oluşan (epistoler) yapısıyla psikolojik derinlik kazanmıştır.'),
  ('Edebiyatımızda Hüseyin Rahmi Gürpınar\'ın baştan sona kaynana-gelin arasındaki mektuplardan oluşturduğu ve Batılı anlamda ilk tam mektup-roman örneklerinden sayılan 1898 tarihli eseri hangisidir?', 'Mutallaka', ['Şık', 'İffet', 'Tesadüf'], '"Mutallaka" (Boşanmış Kadın), tamamı mektuplardan oluşan tekniğiyle Halide Edib\'in "Handan"ından önce yayımlanmış öncü bir mektup-romandır.'),
  ('Dünya edebiyatında mektup-roman türünün en etkili başyapıtlarından sayılan ve romantizm akımının öncüsü olan "Genç Werther\'in Acıları" kimin eseridir?', 'Johann Wolfgang von Goethe', ['Jean-Jacques Rousseau', 'Friedrich Schiller', 'Honore de Balzac'], 'Goethe\'nin 1774\'te yayımladığı "Genç Werther\'in Acıları", Werther\'in dostu Wilhelm\'e yazdığı mektuplardan oluşan dünya çapında ünlü bir mektup-romandır.'),
  ('Antik Roma edebiyatında mektup türünün gelişmesine büyük katkı sağlayan ve dostu Atticus\'a yazdığı yüzlerce mektupla Batı mektup geleneğinin kurucularından sayılan ünlü hatip ve devlet adamı kimdir?', 'Cicero', ['Homeros', 'Sophokles', 'Aristoteles'], 'Romalı devlet adamı ve düşünür Cicero (ve ondan sonra Genç Plinius ile Seneca), Batı edebiyatında edebi ve felsefi mektup türünün temellerini atmıştır.'),
  ('Resmi kurum ve kuruluşlar arasında ya da vatandaşların resmi makamlara bir isteği, şikâyeti arz etmek üzere belirli kurallar çerçevesinde yazdıkları mektup/yazı türüne ne ad verilir?', 'Dilekçe', ['Özel mektup', 'Tebrik kartı', 'Edebî günlük'], 'Bir isteği veya şikâyeti resmi makamlara iletmek için yazılan kısa, nesnel ve kurallı yazılara dilekçe (Osmanlıcada arzuhâl / istidâ) denir.'),
  ('16. yüzyıl divan şairi Bağdatlı Rûhî\'nin toplumsal aksaklıkları eleştirdiği "Terkîb-i Bend"i gibi, Fuzûlî\'nin "Şikâyetname"si de özünde hangi temayı işlemektedir?', 'Toplumsal yozlaşma, bürokratik ilgisizlik ve rüşvet eleştirisi', ['Bahar mevsiminin gelişiyle doğanın canlanmasına duyulan sevinç', 'Osmanlı donanmasının Akdeniz\'de kazandığı deniz zaferlerinin övgüsü', 'İlahi aşk yolunda dervişlerin inzivaya çekilme kuralları'], 'Fuzûlî, Şikâyetname\'de memurların vurdumduymazlığını ve rüşvet beklentisini keskin bir toplumsal eleştiriyle gözler önüne sermiştir.'),
  ('Osmanlı padişahlarının katıldıkları askeri seferlerde konaklama yerlerinin, hava durumunun ve savaş gelişmelerinin günü gününe kaydedildiği rûznâmelere ne ad verilir?', 'Sefer rûznâmesi', ['Sûrname', 'Kıyafetname', 'Pendname'], 'Sefer rûznâmeleri (örneğin Haydar Çelebi Rûznâmesi), Osmanlı ordusunun sefer yürüyüşünü günü gününe kaydeden tarihsel günlüklerdir.'),
  ('Aşağıdaki yazar ve günlük/mektup eseri eşleştirmelerinden hangisi doğrudur?', 'Cahit Sıtkı Tarancı - Ziya\'ya Mektuplar', ['Fuzûlî - Limni ve Malta Mektupları', 'Tomris Uyar - Şikâyetname', 'Nurullah Ataç - Hacivat Günlüğü'], '"Ziya\'ya Mektuplar" Cahit Sıtkı Tarancı\'ya, "Şikâyetname" Fuzûlî\'ye, "Limni ve Malta Mektupları" Ziya Gökalp\'e, "Hacivat Günlüğü" Salah Birsel\'e aittir.'),
  ('Nazım Hikmet\'in hapishane yıllarında Orhan Kemal\'e hikâye ve roman yazarlığı konusunda yol gösterdiği mektupları edebiyatımızda hangi dostluğun ürünü olarak anılır?', 'Bursa Cezaevindeki usta-çırak ve sanat dostluğunun', ['Paris\'teki Jön Türk kongrelerindeki siyasi tartışmaların', 'Servet-i Fünûn dergisi yazı işlerindeki polemiklerin', 'Mavi Yolculuk gezilerindeki arkeoloji araştırmalarının'], 'Bursa Cezaevinde Nazım Hikmet ile tanışan Orhan Kemal, şairin yönlendirmesiyle şiirden öykü ve romana yönelmiş, aralarındaki mektuplaşmalar edebiyat tarihine geçmiştir.'),
];
